interface.definition:
a!localVariables(
  local!confirmation: null,
  local!user: #"_a-0000ef67-4afa-8000-9e56-011c48011c48_1277768"(userid: ri!userid),
  local!userid:if(a!isNotNullOrEmpty(local!user),index(local!user,#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/b9c974e1-800e-4dfe-9d43-14273008fe48",null()),null()),
  local!userorg:if(a!isNotNullOrEmpty(local!userid),#"_a-0000eef8-4604-8000-9e54-011c48011c48_1152489"(user: local!userid,isActive: true()),null()),
  local!isAssignedUser:a!isNotNullOrEmpty(local!userorg),
  #"SYSTEM_SYSRULES_formLayout_v2"(
    titleBar: #"SYSTEM_SYSRULES_headerTemplateFull"(
      title: "Deactivate User",
      secondaryText: "Confirm deactivation",
      backgroundColor: "ACCENT"
    ),
    contents: {
     #"SYSTEM_SYSRULES_cardLayout"(
       contents: {
         #"SYSTEM_SYSRULES_richTextDisplayField"(
           labelPosition: "COLLAPSED",
           value: {
             if(
               local!isAssignedUser,
             {
               #"SYSTEM_SYSRULES_richTextIcon"(
                 icon: "ban",
                 color: "NEGATIVE",
                 size: "MEDIUM_PLUS"
               ),
               "  ",
               #"SYSTEM_SYSRULES_richTextItem_v1"(
                 text: "User Assigned to Organisation",
                 size: "MEDIUM",
                 style: "STRONG",
                 color: "NEGATIVE"
               )
             },
             {
               #"SYSTEM_SYSRULES_richTextIcon"(
                 icon: "exclamation-triangle",
                 color: "#B45F06",
                 size: "MEDIUM_PLUS"
               ),
               "  ",
               #"SYSTEM_SYSRULES_richTextItem_v1"(
                 text: "By performing this action user account will be deactivated",
                 style: "PLAIN",
                 size: "STANDARD"
               )
             }

             )
           },

         ),

       },
       style: if(local!isAssignedUser, "ERROR", "WARN"),
       padding: "MORE",
       shape: "ROUNDED",
       showBorder: true(),
       marginBelow: "MORE"
     ),

      #"SYSTEM_SYSRULES_radioButtonField_v1"(
        label: "Are you sure you want to deactivate this user?",
        labelPosition: "ABOVE",
        choiceLabels: {"Yes", "No"},
        choiceValues: {true, false},
        value: local!confirmation,
        saveInto: local!confirmation,
        choiceLayout: "STACKED",
        required: true,
        validations: {},
        showWhen: not(local!isAssignedUser)
      )
    },
    buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Submit",
          submit: true,
          disabled: local!isAssignedUser,
          saveInto: {
            a!save(
              ri!confirmation,
              local!confirmation
            ),
            a!save(
              ri!button,
              #"_a-0000eeda-0177-8000-9e52-011c48011c48_1085463"
            )
          },
          loadingIndicator: true,
          style: "SOLID"
        )
      },
      secondaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Cancel",
          saveInto: {
            a!save(
              ri!button,
              #"_a-0000eeda-0177-8000-9e52-011c48011c48_1085469"
            )
          },
          validate: false,
          submit: true,
          style: "OUTLINE"
        )
      }
    ),
    showTitleBarDivider: false
  )
)
